export class ScanError extends Error {
  constructor(line, column, reason) {
    super(`${line}:${column}: ${reason}`)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCTUATION = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

const TAB_WIDTH = 4

function isDigit(c) {
  return c >= '0' && c <= '9'
}

function isLetter(c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

function isIdentStart(c) {
  return c !== undefined && (isLetter(c) || c === '_')
}

function isIdentPart(c) {
  return c !== undefined && (isLetter(c) || isDigit(c) || c === '_')
}

function isHexDigit(c) {
  return c !== undefined && (isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))
}

function digitTest(base) {
  if (base === 16) return isHexDigit
  if (base === 8) return (c) => c !== undefined && c >= '0' && c <= '7'
  if (base === 2) return (c) => c === '0' || c === '1'
  return (c) => c !== undefined && isDigit(c)
}

