  constructor(source) {
    this.chars = Array.from(source)
    this.index = 0
    this.line = 1
    this.column = 1
  }

  get done() {
    return this.index >= this.chars.length
  }

  peek(offset = 0) {
    return this.chars[this.index + offset]
  }

  /** Reads one code point, keeping the line and column counts up to date. */
  advance() {
    const c = this.chars[this.index]
    this.index += 1
    if (c === '\n') {
      this.line += 1
      this.column = 1
    } else if (c === '\t') {
      this.column = Math.floor((this.column - 1) / TAB_WIDTH) * TAB_WIDTH + TAB_WIDTH + 1
    } else {
      this.column += 1
    }
    return c
  }

  mark() {
    return { index: this.index, line: this.line, column: this.column }
  }

  textFrom(start) {
    return this.chars.slice(start.index, this.index).join('')
  }

  error(at, reason) {
    return new ScanError(at.line, at.column, reason)
  }

  scan() {
    const tokens = []
    for (;;) {
      this.skipBlanksAndComments()
      if (this.done) return tokens
      tokens.push(this.scanToken())
    }
  }

  skipBlanksAndComments() {
    for (;;) {
      const c = this.peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '/') {
        while (!this.done && this.peek() !== '\n') this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '*') {
        this.skipBlockComment()
        continue
      }
      return
    }
  }

  skipBlockComment() {
    const start = this.mark()
    let depth = 0
    for (;;) {
      if (this.done) throw this.error(start, 'unterminated block comment')
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance()
        this.advance()
        depth += 1
        continue
      }
      if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        depth -= 1
        if (depth === 0) return
        continue
      }
      this.advance()
    }
  }

  scanToken() {
    const start = this.mark()
    const c = this.peek()

    if (c === 'r' && this.peek(1) === '"') return this.scanRawString(start)
    if (isIdentStart(c)) return this.scanWord(start)
    if (isDigit(c)) return this.scanNumber(start)
    if (c === '"') return this.scanString(start)

    for (const punct of PUNCTUATION) {
      if (this.matches(punct)) {
        for (let i = 0; i < punct.length; i += 1) this.advance()
        return { kind: 'punct', line: start.line, column: start.column, text: punct }
      }
    }

    throw this.error(start, `unexpected character ${c}`)
  }

  matches(text) {
    const wanted = Array.from(text)
    for (let i = 0; i < wanted.length; i += 1) {
      if (this.peek(i) !== wanted[i]) return false
    }
    return true
  }

