        const signed = next === '+' || next === '-'
        if (isDigit(next) || (signed && isDigit(this.peek(2)))) {
          this.advance()
          if (signed) this.advance()
          this.digitRun(decimal)
        }
      }
    }

    if (isIdentPart(this.peek())) this.badNumber(start)
    return { kind: 'number', line: start.line, column: start.column, text: this.textFrom(start) }
  }

  scanRawString(start) {
    this.advance()
    this.advance()
    let value = ''
    for (;;) {
      if (this.done) throw this.error(start, 'unterminated string')
      const c = this.advance()
      if (c === '"') {
        return { kind: 'rawstring', line: start.line, column: start.column, value }
      }
      value += c
    }
  }

  scanString(start) {
    this.advance()
    let value = ''
    for (;;) {
      if (this.done) throw this.error(start, 'unterminated string')
      if (this.peek() === '\n') throw this.error(this.mark(), 'newline in string')
      if (this.peek() === '"') {
        this.advance()
        return { kind: 'string', line: start.line, column: start.column, value }
      }
      if (this.peek() === '\\') {
        value += this.scanEscape(start)
        continue
      }
      value += this.advance()
    }
  }

  scanEscape(stringStart) {
    const at = this.mark()
    this.advance()
    if (this.done) throw this.error(stringStart, 'unterminated string')
    if (this.peek() === '\n') throw this.error(this.mark(), 'newline in string')
    const c = this.advance()
    const invalid = () => this.error(at, `invalid escape \\${c}`)

    switch (c) {
      case 'n': return '\n'
      case 't': return '\t'
      case 'r': return '\r'
      case '\\': return '\\'
      case '"': return '"'
      case '0': return '\0'
      case 'x': {
        if (!isHexDigit(this.peek()) || !isHexDigit(this.peek(1))) throw invalid()
        const digits = this.advance() + this.advance()
        return String.fromCharCode(parseInt(digits, 16))
      }
      case 'u': {
        if (this.peek() !== '{') throw invalid()
        this.advance()
        let digits = ''
        while (isHexDigit(this.peek())) digits += this.advance()
        if (digits.length === 0 || this.peek() !== '}') throw invalid()
        this.advance()
        const code = parseInt(digits, 16)
        if (!Number.isFinite(code) || code > 0x10ffff) throw invalid()
        return String.fromCodePoint(code)
      }
      default:
        throw invalid()
    }
  }
}

